"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["95098"],{28356(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>c,frontMatter:()=>o,contentTitle:()=>s,toc:()=>h,assets:()=>r});var n=JSON.parse('{"id":"tangfen/chliuwill","title":"","description":"If Chuanliu truly understood what labor is and what Marx\'s labor theory of value is, he would not have posted \\"What if we replace \'labor theory of value\' with \'Tangfen\'s will theory\' (Chuanliu26:44)1558B (1/15/0),\\" because he treats labor as something equivalent to his own will!","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/chliuwill.md","sourceDirName":"tangfen","slug":"/tangfen/chliuwill","permalink":"/en/tangfen/chliuwill","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"chliuwill","title":"","hide_table_of_contents":true,"sidebar_label":"Chuanliu, let me tell you what things are like \\"Chuanliu\'s will\\"! But labor is not!"},"sidebar":"tangfenSidebar","previous":{"title":"Math, of course the labor theory of value can be criticized!","permalink":"/en/tangfen/labortheoryofvalue"},"next":{"title":"Another suggestion: if refuting Marx or Ms. Chan, first understand their ideas clearly \u2014 don\'t fabricate on your own!","permalink":"/en/tangfen/anothersuggestion"}}'),l=a(74848),i=a(28453);let o={id:"chliuwill",title:"",hide_table_of_contents:!0,sidebar_label:'Chuanliu, let me tell you what things are like "Chuanliu\'s will"! But labor is not!'},s='Chuanliu, Let Me Tell You What "Chuanliu\'s Will"-Type Things Actually Are! But Labor Is Not One!',r={},h=[];function u(e){let t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,l.jsxs)(l.Fragment,{children:[(0,l.jsx)(t.header,{children:(0,l.jsx)(t.h1,{id:"chuanliu-let-me-tell-you-what-chuanlius-will-type-things-actually-are-but-labor-is-not-one",children:'Chuanliu, Let Me Tell You What "Chuanliu\'s Will"-Type Things Actually Are! But Labor Is Not One!'})}),"\n",(0,l.jsx)(t.p,{children:"If Chuanliu truly understood what labor is and what Marx's labor theory of value is, he would not have posted \"What if we replace 'labor theory of value' with 'Tangfen's will theory' (Chuanliu: 2006-08-11 14:26:44)1558B (1/15/0),\" because he treats labor as something equivalent to his own will!"}),"\n",(0,l.jsx)(t.p,{children:"In Marx, labor is a holistic, historical concept, not a single factor. On the contrary, it is precisely supply and demand in Western economics that are \"Chuanliu's will\"-type things! As for Western economics' economic man hypothesis and analysis of human desires -- these are all \"Chuanliu's will\"-type things! And then there's Stalin's productive forces, Proudhon's labor time, and so on -- all \"Chuanliu's will\"-type things!"}),"\n",(0,l.jsx)(t.p,{children:"In Marx, value comes from the totality of relations between people in the social structure. What can determine value can only be the totality of relations between people in the holistic social structure, and the essence of this structure comes from labor relations. This is because the basic constitution of modern society comes from labor relations -- for example, the most fundamental capital-labor relationship, class relations, and so on. Fundamentally speaking, the relations between people in modern society all ultimately trace back to labor relations. This is actually consistent with Marx's thesis that the economic base determines the superstructure. Without Marx's historical materialism, there is no Marxian labor theory of value!"}),"\n",(0,l.jsx)(t.p,{children:'Labor, value -- these are all historical, holistic categories that cannot be encompassed by any single factor. The different factors that the labor category manifests in different historical periods precisely reflect changes in social structure! Capitalist labor and pre-capitalist labor are different, because the social structure constituting labor has changed. The classical assumption that there exists some a priori, eternally unchanging labor is precisely a "Chuanliu\'s will"-type thing, and has nothing whatsoever to do with Marx!'})]})}function c(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,l.jsx)(t,{...e,children:(0,l.jsx)(u,{...e})}):u(e)}},28453(e,t,a){a.d(t,{R:()=>o,x:()=>s});var n=a(96540);let l={},i=n.createContext(l);function o(e){let t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(l):e.components||l:o(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);